'use strict';
let careerPDFLoading=null;
function careerPDFLibrary(){if(globalThis.PDFLib)return Promise.resolve(globalThis.PDFLib);if(!careerPDFLoading)careerPDFLoading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/pdf-lib.min.js';s.onload=()=>resolve(globalThis.PDFLib);s.onerror=()=>{s.remove();careerPDFLoading=null;reject(Error('Could not load the PDF tool. Retry when connected, or use Print / Save as PDF.'))};document.head.append(s)});return careerPDFLoading}
async function careerMakePDF(data,profile,lib,images={}){
 const {PDFDocument,StandardFonts,rgb}=lib,doc=await PDFDocument.create(),normal=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold),green=rgb(.184,.439,.282),black=rgb(.07,.07,.07),white=rgb(1,1,1),gray=rgb(.93,.95,.94),width=595.28,height=841.89,margin=34,W=width-margin*2,bottom=34;
 let page,y,pageNo=0;
 const clean=v=>String(v??'').replace(/\r/g,'').replace(/\t/g,'    ');
 function lines(text,font,size,max){const out=[];for(const paragraph of clean(text).split('\n')){let line='';for(const word of paragraph.split(' ')){if(!word)continue;const candidate=line?line+' '+word:word;if(font.widthOfTextAtSize(candidate,size)<=max){line=candidate;continue}if(line){out.push(line);line=''}let part='';for(const ch of word){if(font.widthOfTextAtSize(part+ch,size)>max&&part){out.push(part);part=''}part+=ch}line=part}out.push(line)}return out.length?out:['']}
 function text(t,x,yy,size=9,font=normal,color=black){if(t)page.drawText(t,{x,y:yy,size,font,color})}
 function newPage(){page=doc.addPage([width,height]);y=height-margin;pageNo++;text(profile.fullName||'Seafarer CV',margin,18,8);text(String(pageNo),width-margin-12,18,8)}
 function ensure(h){if(y-h<bottom)newPage()}
 function band(title){ensure(44);page.drawRectangle({x:margin,y:y-20,width:W,height:20,color:green});text(title,margin+6,y-14,9,bold,white);y-=20}
 function drawRow(cells,widths,header=false,size=9,repeat=null,personal=false){const wraps=cells.map((cell,i)=>lines(cell,header||personal&&i%2===0?bold:normal,personal&&i%2===0?8:size,widths[i]-8));let offset=0,total=Math.max(1,...wraps.map(a=>a.length));const lineHeight=size+3,pad=4;
  if(y-(total*lineHeight+pad*2)<bottom&&total*lineHeight+pad*2<height-margin-bottom-65){newPage();if(repeat)repeat()}
  while(offset<total){let available=Math.floor((y-bottom-pad*2)/lineHeight);if(available<1){newPage();if(repeat)repeat();available=Math.floor((y-bottom-pad*2)/lineHeight)}const count=Math.min(total-offset,available),h=count*lineHeight+pad*2;let x=margin;
   cells.forEach((_,i)=>{page.drawRectangle({x,y:y-h,width:widths[i],height:h,borderColor:black,borderWidth:.5,...header?{color:gray}:{}});const font=header||personal&&i%2===0?bold:normal,fs=personal&&i%2===0?8:size;wraps[i].slice(offset,offset+count).forEach((line,j)=>text(line,x+4,y-pad-fs-j*lineHeight,fs,font));x+=widths[i]});y-=h;offset+=count;if(offset<total){newPage();if(repeat)repeat()}}
 }
 function paragraph(value,size=10){const ls=lines(value,normal,size,W-12);for(const line of ls){ensure(size+5);text(line,margin+6,y-size-3,size);y-=size+5}y-=5}
 try{
 newPage();const name=lines(profile.fullName||'',bold,23,W-120);name.forEach((line,i)=>text(line,margin,y-27-i*27,23,bold));text(profile.rank||'',margin,y-35-name.length*27,11);
 if(images.portrait&&data.exportOptions.photo){const image=await doc.embedJpg(images.portrait);page.drawImage(image,{x:width-margin-99.2,y:y-127.6,width:99.2,height:127.6})}else{page.drawRectangle({x:width-margin-99.2,y:y-127.6,width:99.2,height:127.6,borderColor:rgb(.6,.6,.6),borderWidth:.5});text('Photo',width-margin-64,y-67,9)}y-=Math.max(145,name.length*27+65);
 for(const section of careerCVSections(data)){
  band(section.title);if(section.text!==undefined){paragraph(section.text||' ',10);continue}const count=section.head?.length||4,widths=section.personal?[W*.18,W*.32,W*.18,W*.32]:count===9?[.10,.11,.11,.10,.14,.12,.09,.08,.15].map(v=>v*W):Array(count).fill(W/count),size=count===9?8:9;
  const repeat=()=>{band(section.title+' (continued)');if(section.head)drawRow(section.head,widths,true,size)};
  if(section.head)drawRow(section.head,widths,true,size);const rows=section.rows.length?section.rows:[Array(count).fill('')];for(const row of rows){const address=section.personal&&!row[2]&&!row[3];drawRow(address?row.slice(0,2):row,address?[W*.18,W*.82]:widths,false,size,repeat,section.personal)}y-=10;
 }
 if(data.exportOptions.declaration){ensure(65);paragraph('I hereby certify that the information given above is true and correct to the best of my knowledge and belief and that I have not withheld any information that would affect my application unfavorably.',9)}
 ensure(85);if(images.signature&&data.exportOptions.signature){const image=await doc.embedJpg(images.signature),dims=image.scaleToFit(156,42);page.drawImage(image,{x:width-margin-190+(190-dims.width)/2,y:y-45,width:dims.width,height:dims.height})}y-=52;const nameLines=lines(profile.fullName||'',bold,10,190);nameLines.forEach(line=>{ensure(14);text(line,width-margin-190,y,10,bold);y-=14});page.drawLine({start:{x:width-margin-190,y:y+10},end:{x:width-margin,y:y+10},thickness:.5,color:black});text('Signature over Printed Name',width-margin-190,y-5,9);doc.setTitle('Seafarer CV');doc.setSubject('User-selected career records');return await doc.save();
 }catch(e){if(/encode|WinAnsi|character/i.test(e.message))throw Error('This PDF font cannot represent a character in your entries. Use Print / Save as PDF to preserve your language.');throw e}
}
async function careerDownloadPDF(){if(!careerData||careerBusy)return;const owner=careerAccount(),epoch=careerEpoch,data=structuredClone(careerData),profile={...careerPerson(data),rank:state.profile.rank||''},status=document.getElementById('careerStatus');if(status)status.textContent='Preparing your PDF on this device…';try{const lib=await careerPDFLibrary(),images={};for(const key of ['portrait','signature'])if(data[key]&&data.exportOptions[key==='portrait'?'photo':'signature']){const blob=await careerBlob(owner,data[key]);if(!blob)throw Error('A selected CV image is missing. Restore your backup or deselect it.');images[key]=await blob.arrayBuffer()}if(owner!==careerAccount()||epoch!==careerEpoch)return;const bytes=await careerMakePDF(data,profile,lib,images);if(owner!==careerAccount()||epoch!==careerEpoch)return;careerDownload(new Blob([bytes],{type:'application/pdf'}),'Toolbox-CV.pdf');if(status)status.textContent='PDF generated. Check your downloads.'}catch(e){if(owner===careerAccount()&&epoch===careerEpoch&&status)status.textContent=e.message}}
